void InGameHeroSelectInterface::Impl::OnButtonPressed(const char *name)
{
	if (strncmp(name, "Hero", 4) != 0)
		return;
	int index = atoi(name + 4) - 1;
	if (index < 0 || index >= MAX_HERO_SLOTS)
		return;
	if (m_slots[index].m_flag16)
	{
		SelectNearestBuilder(false);
		return;
	}
	if (m_slots[index].m_hero == m_data->m_heroes.end())
		return;
	Object *object = TheGameLogic->findObjectByID(*m_slots[index].m_hero);
	if (object == 0)
		return;
	if (object->getTemplate()->isKindOf(KINDOF_HERO) && object->m_containedBy != 0)
		object = object->m_containedBy;
	if (object == 0 || !object->isSelectable())
		return;
	Drawable *drawable = object->getDrawable();
	if (drawable == 0)
		return;
	Object *rider = drawable->getObject();
	if (rider != 0)
	{
		Object *mount = rider->m_containedBy;
		if (mount != 0 && mount->getTemplate()->isKindOf0x115())
		{
			object = mount;
			drawable = object->getDrawable();
		}
	}

	const _STL::list<Drawable *> *selected = TheInGameUI->getAllSelectedDrawables();
	if (TheInGameUI->m_8BA && selected->size() != 0 && !(selected->size() == 1 && selected->front() == drawable))
	{
		bool found = false;
		_STL::list<Drawable *>::const_iterator it = selected->begin();
		while (it != selected->end())
		{
			if (found)
				break;
			if (*it == drawable)
				found = true;
			else
				++it;
		}
		if (found)
		{
			GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_REMOVE_FROM_SELECTED_GROUP);
			msg->appendObjectIDArgument(object->getID());
			TheInGameUI->deselectDrawable(drawable);
		}
		else
		{
			GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_CREATE_SELECTED_GROUP);
			msg->appendBooleanArgument(false);
			msg->appendObjectIDArgument(object->getID());
			TheInGameUI->selectDrawable(drawable);
		}
	}
	else if (selected->size() == 1 && selected->front() == drawable)
	{
		TheTacticalView->lookAt(drawable->getPosition());
	}
	else
	{
		TheInGameUI->deselectAllDrawables();
		GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_CREATE_SELECTED_GROUP);
		msg->appendBooleanArgument(true);
		msg->appendObjectIDArgument(object->getID());
		TheInGameUI->selectDrawable(drawable);
	}
}

